import random
from collections import deque

def girth(adj):
    """Compute girth (shortest cycle length) of graph. Returns float('inf') if acyclic."""
    n = len(adj)
    best = float('inf')
    for start in range(n):
        parent = [-1] * n
        dist = [-1] * n
        q = deque([start])
        dist[start] = 0
        while q:
            v = q.popleft()
            for u in adj[v]:
                if dist[u] == -1:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    q.append(u)
                elif u != parent[v] and parent[v] != u:
                    if parent[v] != u and parent[u] != v:
                        cycle_len = dist[v] + dist[u] + 1
                        if cycle_len < best:
                            best = cycle_len
                            if best <= 6:
                                return best
    return best

def random_bipartite(left_size, right_size, min_edges, max_tries=50000):
    total = left_size + right_size
    left = list(range(left_size))
    right = list(range(left_size, total))

    for attempt in range(max_tries):
        adj = [set() for _ in range(total)]
        possible_edges = [(l, r) for l in left for r in right]
        random.shuffle(possible_edges)

        edges_count = 0
        for l, r in possible_edges:
            if edges_count >= min_edges:
                break

            # C4 check: does there exist l2 != l such that l2 is also adjacent to r,
            # and l and l2 share another neighbor?
            creates_c4 = False
            for l2 in left:
                if l2 != l and r in adj[l2]:
                    if adj[l] & adj[l2]:
                        creates_c4 = True
                        break
            if creates_c4:
                continue

            # C6 check: adding (l,r) creates a 6-cycle?
            # A 6-cycle would be l-r-l2-r2-l3-r3-l
            # We need: l2 adjacent to r, l2 adjacent to r2, l3 adjacent to r2, l3 adjacent to r3, l adjacent to r3
            creates_c6 = False
            for r3 in adj[l]:
                for l3 in left:
                    if l3 == l or r3 not in adj[l3]:
                        continue
                    for r2 in adj[l3]:
                        if r2 == r or r2 == r3:
                            continue
                        for l2 in left:
                            if l2 == l or l2 == l3:
                                continue
                            if r in adj[l2] and r2 in adj[l2]:
                                creates_c6 = True
                                break
                        if creates_c6:
                            break
                    if creates_c6:
                        break
                if creates_c6:
                    break

            if creates_c6:
                continue

            adj[l].add(r)
            adj[r].add(l)
            edges_count += 1

        if edges_count >= min_edges:
            return adj, edges_count
    return None, 0

# Try with 10 left, 11 right
adj, cnt = random_bipartite(10, 11, 40, 20000)
print("Edges found:", cnt)
if adj:
    print("Success!")
    # Verify girth
    g = girth(adj)
    print("Girth:", g)
    # Count edges
